GameTransaction.methods.add_change:
extends Node

const PICKUP_STORE: String = "world_pickups"
const WALLET_STORE: String = "player_wallet"
const COIN_POUCH: String = "coin_pouch_at_gate"
const POUCH_COINS: int = 8

func _ready() -> void:
    var coordinator: TransactionCoordinator = TransactionCoordinator.new()
    var registered: Error = coordinator.register_store(
        PICKUP_STORE, {COIN_POUCH: true}, _prepare_pickups
    )
    if registered == OK:
        registered = coordinator.register_store(WALLET_STORE, {"coins": 0}, _prepare_wallet)
    if registered != OK:
        push_error(error_string(registered))
        return

    # Run these changes together when the authority awards a pickup.
    var collect: GameTransaction = coordinator.begin()
    var pickup_revision: int = coordinator.get_store_revision(PICKUP_STORE)
    var wallet_revision: int = coordinator.get_store_revision(WALLET_STORE)
    var queued: Error = collect.add_change(PICKUP_STORE, {"take": COIN_POUCH}, pickup_revision)
    if queued == OK:
        queued = collect.add_change(WALLET_STORE, {"add": POUCH_COINS}, wallet_revision)
    if queued != OK:
        push_warning(error_string(queued))
        return

    var committed: Dictionary = coordinator.commit(collect)
    if not committed.get("ok", false):
        push_warning(String(committed.get("message", "Pickup rejected.")))
        return

    var pickups: Dictionary = coordinator.read_store(PICKUP_STORE)
    var wallet: Dictionary = coordinator.read_store(WALLET_STORE)
    print("Pickup still visible: ", pickups[COIN_POUCH], "; HUD coins: ", wallet["coins"])

func _prepare_pickups(state: Dictionary, operations: Array, _context: Dictionary) -> Dictionary:
    for operation: Dictionary in operations:
        var pickup_id: String = String(operation["take"])
        if not state.get(pickup_id, false):
            return {"ok": false, "message": "This pickup was already collected."}
        state[pickup_id] = false
    return {"ok": true, "state": state}

func _prepare_wallet(state: Dictionary, operations: Array, _context: Dictionary) -> Dictionary:
    for operation: Dictionary in operations:
        var amount: int = int(operation["add"])
        if amount <= 0:
            return {"ok": false, "message": "A pickup must award a positive amount."}
        state["coins"] = int(state["coins"]) + amount
    return {"ok": true, "state": state}

LocalPlayerView.methods.get_camera:
extends Node

const WORLD_ID: StringName = &"training_room"
const CAMERA_HEIGHT: float = 1.6
const VIEW_PATH: NodePath = ^"LocalPlayerView"

# Assign a Node3D world scene with at least one PlayerSpawnPoint.
@export var world_scene: PackedScene

func _ready() -> void:
    if world_scene == null:
        push_error("Assign the training-room scene.")
        return

    var player_scene: PackedScene = _make_player_scene()
    if player_scene == null:
        return

    var definition: GameDefinition = GameRuntime.configure()
    definition = definition.with_starting_world(WORLD_ID, world_scene)
    definition = definition.with_player(player_scene)
    var game: GameRuntime = definition.boot(self)
    if game == null:
        push_error("Could not create the game.")
        return
    var operation: GameOperation = game.play_solo()
    var started: Dictionary = await operation.wait()
    if not started.get("ok", false):
        push_warning(String(started.get("message", "Could not start the game.")))
        return

    var local_player: Node3D = game.get_local_player()
    if local_player == null:
        return
    var local_view: LocalPlayerView = local_player.get_node(VIEW_PATH)
    var active_camera: Camera3D = local_view.get_camera()
    if active_camera != null and active_camera.is_current():
        print("The local player is looking through ", active_camera.name)

func _make_player_scene() -> PackedScene:
    var actor: Node3D = Node3D.new()
    var eyes: Camera3D = Camera3D.new()
    eyes.name = &"FirstPersonCamera"
    eyes.position.y = CAMERA_HEIGHT
    actor.add_child(eyes)
    eyes.owner = actor
    # Pack the view with the player so its references exist before spawning.
    var view: LocalPlayerView = LocalPlayerView.new()
    view.name = &"LocalPlayerView"
    actor.add_child(view)
    view.owner = actor
    view.camera = eyes
    var packed: PackedScene = PackedScene.new()
    var packed_status: Error = packed.pack(actor)
    actor.free()
    if packed_status != OK:
        push_error(error_string(packed_status))
        return null
    return packed

