SteamPublisherHost.methods._resolve_encr:
extends SteamPublisherHost

const ENCRYPTED_TICKET_KEY_BYTES: int = 32

# Set this to a backend-only secret-store lookup that returns raw key bytes.
var load_ticket_key: Callable

func _resolve_encrypted_ticket_key(reference: StringName) -> PackedByteArray:
    if not load_ticket_key.is_valid():
        return PackedByteArray()
    var key: PackedByteArray = load_ticket_key.call(reference)
    return key if key.size() == ENCRYPTED_TICKET_KEY_BYTES else PackedByteArray()

SteamPublisherHost.methods._resolve_secr:
extends SteamPublisherHost

const PUBLISHER_KEY_REFERENCE: StringName = &"STEAM_PUBLISHER_KEY"

func _resolve_secret(reference: StringName) -> String:
    if reference != PUBLISHER_KEY_REFERENCE:
        return ""
    return OS.get_environment(String(PUBLISHER_KEY_REFERENCE))

SteamPurchaseStore.methods._load_order:
extends SteamPurchaseStore

# Load the exact order ID from the specified app and environment.
var fetch_saved_order: Callable

func _load_order(app_id: int, environment: SteamPublisherSettings.Environment, order_id: String) -> SteamPublisherPurchaseOrderResult:
    if not fetch_saved_order.is_valid():
        return SteamPublisherPurchaseOrderResult.create(ERR_UNCONFIGURED)
    return fetch_saved_order.call(app_id, environment, order_id) as SteamPublisherPurchaseOrderResult

