const SUBSCRIPTION_LIMIT: int = 24

@export var steam_client: SteamClient
@export var subscription_list: ItemList
@export var status_label: Label

# Connect Refresh in your Workshop screen to this method.
func refresh_workshop_list() -> void:
    if steam_client == null or subscription_list == null or status_label == null:
        return
    var workshop: SteamWorkshop = steam_client.workshop()
    if workshop == null:
        status_label.text = "Workshop unavailable"
        return
    var result: SteamWorkshopSubscriptionsResult = workshop.subscriptions(SUBSCRIPTION_LIMIT)
    if not result.ok:
        status_label.text = result.message
        return

    var subscriptions: SteamWorkshopSubscriptions = result.value
    subscription_list.clear()
    for published_id: String in subscriptions.published_ids:
        subscription_list.add_item("Workshop item " + published_id)
    status_label.text = "Showing %d of %d subscribed items." % [
        subscription_list.item_count, subscriptions.total_count
    ]

TransactionCoordinator.methods.register_:
extends Node

const WALLET_STORE: String = "player_wallet"
const INITIAL_COINS: int = 10
const REWARD_COINS: int = 5

func _ready() -> void:
    var coordinator: TransactionCoordinator = TransactionCoordinator.new()
    var initial_wallet: Dictionary = {"coins": INITIAL_COINS}
    var registered: Error = coordinator.register_store(
        WALLET_STORE, initial_wallet, _prepare_wallet
    )
    if registered != OK:
        push_error(error_string(registered))
        return

    var reward: GameTransaction = coordinator.begin()
    var revision: int = coordinator.get_store_revision(WALLET_STORE)
    var queued: Error = reward.add_change(WALLET_STORE, {"add": REWARD_COINS}, revision)
    if queued != OK:
        push_warning(error_string(queued))
        return

    var committed: Dictionary = coordinator.commit(reward)
    if not committed.get("ok", false):
        push_warning(String(committed.get("message", "Reward rejected.")))
        return

    var wallet: Dictionary = coordinator.read_store(WALLET_STORE)
    print("Show this wallet balance in the HUD: ", wallet["coins"])

func _prepare_wallet(state: Dictionary, operations: Array, _context: Dictionary) -> Dictionary:
    for operation: Dictionary in operations:
        var amount: int = int(operation.get("add", 0))
        if amount <= 0:
            return {"ok": false, "message": "A reward must be positive."}
        state["coins"] = int(state["coins"]) + amount
    return {"ok": true, "state": state}

WorldSession.methods.host:
extends Node

const GAME_PORT: int = 7000
const SPAWN_POINTS_PATH: NodePath = ^"SpawnPoints"
const CAMERA_PATH: NodePath = ^"Camera3D"

# Use the same world and player scenes on host and guest.
# The direct Marker3D children of SpawnPoints provide the available slots.
@export var world_scene: PackedScene
@export var player_scene: PackedScene
@export var host_button: Button

var _session: WorldSession

func _ready() -> void:
    if world_scene == null or player_scene == null or host_button == null:
        push_error("Assign the world, player scene, and Host button.")
        return

    var definition: WorldSessionDefinition = WorldSession.configure()
    definition = definition.with_world(world_scene)
    definition = definition.with_players(player_scene, SPAWN_POINTS_PATH)
    definition = definition.with_local_view(CAMERA_PATH).on_port(GAME_PORT)
    _session = definition.create()
    add_child(_session)
    host_button.pressed.connect(_host_world)

func _host_world() -> void:
    var started: Error = _session.host()
    if started != OK:
        push_warning("Could not host the world. " + error_string(started))
        return

    host_button.disabled = true
    print("Guests can join this host on UDP port ", _session.get_port())

WorldSession.methods.join:
extends Node

const GAME_PORT: int = 7000
const SPAWN_POINTS_PATH: NodePath = ^"SpawnPoints"
const CAMERA_PATH: NodePath = ^"Camera3D"

# Assign the same scenes as the host and enter its reachable address.
@export var world_scene: PackedScene
@export var player_scene: PackedScene
@export var host_address: String = "127.0.0.1"

var _session: WorldSession

func _ready() -> void:
    if world_scene == null or player_scene == null:
        push_error("Assign the world and player scenes used by the host.")
        return

    var definition: WorldSessionDefinition = WorldSession.configure()
    definition = definition.with_world(world_scene)
    definition = definition.with_players(player_scene, SPAWN_POINTS_PATH)
    definition = definition.with_local_view(CAMERA_PATH).on_port(GAME_PORT)
    _session = definition.create()
    add_child(_session)
    _session.state_changed.connect(_on_state_changed)
    _session.session_ended.connect(_on_session_ended)

    var started: Error = _session.join(host_address)
    if started != OK:
        push_error("Connection could not start. " + error_string(started))

func _on_state_changed(state: int) -> void:
    if state != WorldSession.RUNNING:
        return
    var player: Node3D = _session.get_local_player()
    if player != null:
        print("Joined the world as ", player.name)

func _on_session_ended(reason: StringName) -> void:
    push_warning("Session ended. " + String(reason))

